const projectGrid=document.querySelector('#projects');
projectGrid.innerHTML=projects.map((p,i)=>{const tags=p.kind.split(' · ').slice(0,3);return `<article class="project project--${p.id}" style="--project-color:${p.color}" tabindex="0" role="button" aria-label="Open ${p.title} case study" data-id="${p.id}"><div class="project-image"><div class="project-topline">${tags.map(tag=>`<span>${tag}</span>`).join('')}</div><img src="${img(p.image)}" alt="${p.title} project visual" loading="${i>1?'lazy':'eager'}"><div class="project-shade"></div><div class="project-meta"><p>0${i+1} / ${p.tag}</p><h3>${p.title} <b class="project-arrow-circle" aria-hidden="true"><svg class="arrow-svg" width="12" height="12" viewBox="0 0 14 14" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M2.5 11.5L11.5 2.5"/><path d="M4 2.5h7.5V10"/></svg></b></h3></div></div></article>`}).join('');
const expStack=document.querySelector('#experiments-stack');
if(expStack){expStack.innerHTML=visualExplorations.map((exp,idx)=>`<article class="exp-card" data-index="${idx}" style="z-index:${idx+1}" tabindex="0" role="button" aria-label="View ${exp.title}"><div class="exp-card-header"><div class="exp-card-meta-left"><span class="exp-pill">${exp.num}</span><span class="exp-pill">${exp.category}</span><h3 class="exp-card-title">${exp.title}</h3></div><div class="exp-card-action"><span>Expand Preview</span><span class="exp-card-arrow" aria-hidden="true"><svg class="arrow-svg" width="12" height="12" viewBox="0 0 14 14" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M2.5 11.5L11.5 2.5"/><path d="M4 2.5h7.5V10"/></svg></span></div></div><div class="exp-card-media"><img src="${img(exp.image)}" alt="${exp.title}" loading="${idx>1?'lazy':'eager'}"><div class="exp-card-scrim"></div><div class="exp-card-badge"><span>Click to preview full design</span> <span class="exp-card-badge-arrow" aria-hidden="true"><svg class="arrow-svg" width="12" height="12" viewBox="0 0 14 14" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M2.5 11.5L11.5 2.5"/><path d="M4 2.5h7.5V10"/></svg></span></div></div><div class="exp-card-footer"><p>${exp.desc}</p></div></article>`).join('');}
const dialog=document.querySelector('#case-study'), content=document.querySelector('#case-content');
function openCase(p){if(p.id==='owls'){openOwlsCase(p);return}if(p.id==='mind'){openSheffieldCase(p);return}if(p.id==='callum'){openCallumCase(p);return}if(p.id==='scotrail'){openScotRailCase(p);return}if(p.id==='detox'){openDetoxCase(p);return}if(p.id==='furnich'){openFurnichCase(p);return}content.innerHTML=`<section class="case-hero" style="--case:${p.color}"><p class="eyebrow">${p.kind}</p><h1>${p.title}</h1><p>${p.intro}</p><img src="${img(p.image)}" alt="${p.title} hero visual"></section><section class="case-body" style="--accent:${p.color}"><div class="case-intro"><p class="eyebrow">Overview</p><p>${p.about}</p></div><div class="case-sections"><h2>The challenge</h2><p>${p.challenge}</p>${p.sections.map(s=>`<h3>${s[0]}</h3><p>${s[1]}</p>`).join('')}<div class="outcome"><p>${p.outcome}</p></div></div><div class="case-gallery">${p.gallery.map((x,i)=>`<figure><img src="${img(x)}" alt="${p.title} visual ${i+1}" loading="lazy"></figure>`).join('')}</div></section>`;dialog.showModal();dialog.scrollTop=0;document.body.style.overflow='hidden'}
function openDetoxCase(p){const base='UI:UX DESIGN PROJECTS/Images/Digital Detox Images/';const rd='UI:UX DESIGN PROJECTS/Images/Digital Detox Images/Real designs/';content.innerHTML=`<section class="case-hero case-hero--detox" style="--case:${p.color}"><p class="eyebrow">UI/UX design · Product design · Design sprint · 2024</p><h1>Digital Detox</h1><p>A gamified mobile app concept built in four days — turning screen-time reduction into something measurable, motivating and rewarding.</p><img src="${img(base+'hero.jpg')}" alt="Digital Detox — Unplug and Collect campaign visual"></section><article class="case-body detox-case" style="--accent:${p.color}"><div class="case-intro"><p class="eyebrow">Project overview</p><p>Digital Detox is a concept mobile application designed to help 18–35 year-olds reduce screen time and create a healthier balance between digital and real-world activity. The product uses gamification to make behaviour change feel achievable and rewarding rather than restrictive.</p></div><section class="case-section"><div><p class="eyebrow">01 / The problem</p></div><div><h2>Screen time is easy to measure. Changing behaviour is harder.</h2><p>Simply showing someone how much time they spend on their phone does not give them a compelling reason to change. The concept explored a different question:</p><blockquote class="detox-quote">What if reducing screen time felt like completing a challenge rather than giving something up?</blockquote><p>The answer was a gamified experience where users set goals, track progress, earn rewards and turn saved time into something tangible.</p><div class="journey"><span>Set goal</span><i class="journey-sep" aria-hidden="true"><svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round"><path d="M5 12h14M13 6l6 6-6 6"/></svg></i><span>Use less</span><i class="journey-sep" aria-hidden="true"><svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round"><path d="M5 12h14M13 6l6 6-6 6"/></svg></i><span>Save time</span><i class="journey-sep" aria-hidden="true"><svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round"><path d="M5 12h14M13 6l6 6-6 6"/></svg></i><span>Earn reward</span><i class="journey-sep" aria-hidden="true"><svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round"><path d="M5 12h14M13 6l6 6-6 6"/></svg></i><span>Stay motivated</span></div><figure class="case-evidence case-evidence--detox-orange"><img src="${img(rd+'Frame 1.png')}" alt="Digital Detox — problem space: ADHD, doom scrolling, anxiety, relationship issues" loading="lazy"><figcaption>The problem space — excessive screen time is linked to anxiety, doom scrolling, ADHD and relationship issues. The community feature connects users facing similar challenges.</figcaption></figure></div></section><section class="case-section"><div><p class="eyebrow">02 / The design sprint</p></div><div><h2>From idea to MVP in four days.</h2><p>The project was completed as a focused four-day design sprint in 2024. The tight timeframe required prioritising the core experience over feature expansion — and demonstrated how accumulated design knowledge enables faster, more confident decision-making.</p><div class="detox-sprint-steps"><div><b>Day 01</b><span>Concept + Problem</span></div><div><b>Day 02</b><span>Product structure + Features</span></div><div><b>Day 03</b><span>UI design + Interaction</span></div><div><b>Day 04</b><span>Prototype + Refinement</span></div></div><figure class="case-evidence case-evidence--light"><img src="${img(rd+'Instagram Story 1 1.png')}" alt="Digital Detox brand hero — Life beyond the screen" loading="lazy"><figcaption>Product concept — Life beyond the screen. The iPhone 15 Pro mockup shows the home dashboard with the Detox Score, Community Challenge and Task Quickie.</figcaption></figure></div></section><section class="case-section"><div><p class="eyebrow">03 / Onboarding</p></div><div><h2>Get started with one tap.</h2><p>The welcome screen introduces the product identity and gets users into the experience with the minimum possible friction. The Detox logo — a balanced, stacked form — gives the app a calm, approachable personality from the first screen.</p><figure class="case-evidence case-evidence--light detox-phone-figure"><img src="${img(rd+'Welcome.png')}" alt="Digital Detox welcome screen — Get Started, Log in, Sign up" loading="lazy"><figcaption>Welcome screen — product identity, single CTA and social proof photo create an immediate sense of the real-world context the app is designed to support.</figcaption></figure></div></section><section class="case-section"><div><p class="eyebrow">04 / Dashboard</p></div><div><h2>Everything the user needs, visible at once.</h2><p>The homepage was designed to communicate the app's mission while providing direct access to all core tools. The Companion card surfaces a motivational message; the Community Challenge and Detox Score give users a quick performance read; Task Quickie supports in-the-moment focus sessions.</p><div class="detox-screens-pair"><figure class="case-evidence case-evidence--light detox-phone-figure"><img src="${img(rd+'Daily inspiration.png')}" alt="Digital Detox home dashboard — Detox Score 80, Community Challenge, Task Quickie, Discover now" loading="lazy"><figcaption>Home dashboard — personalised greeting, Detox Score, active challenge and Pomodoro-style Task Quickie in a single scrollable view.</figcaption></figure><figure class="case-evidence detox-phone-figure"><img src="${img(base+'deviceframes.png')}" alt="Digital Detox — two device mockups showing home and progress tracking screens" loading="lazy"><figcaption>Two-screen overview — the home dashboard (left) alongside the progress tracking view with screen-time chart and hourly unplugged gamification (right).</figcaption></figure></div></section><section class="case-section"><div><p class="eyebrow">05 / Companion</p></div><div><h2>Support that feels present, not intrusive.</h2><p>The Companion provides dynamic motivational quotes, tips and timely reminders. It gives the product a more human personality — ongoing encouragement that keeps users focused without relying on system notifications alone. The dynamic logo humanises the experience.</p><figure class="case-evidence case-evidence--light detox-phone-figure"><img src="${img(base+'iPhone 16 Pro Max 2.png')}" alt="Digital Detox — companion motivational quote and progress tracking screen" loading="lazy"><figcaption>Companion in context — the motivational chip appears at the top of every screen. Below it, the screen-time chart and hourly unplugged progress card give users continuous awareness of their behaviour.</figcaption></figure></div></section><section class="case-section"><div><p class="eyebrow">06 / Goal setting</p></div><div><h2>Set a goal. Keep it visible. Stay on track.</h2><p>Goal setting was designed to be quick and easy, using a familiar progress-indicator pattern similar to a media player. Users set their daily screen-time limit, configure Pomodoro sessions and choose their meditation time. The persistent progress bar at the bottom of the screen keeps the active goal visible without requiring extra navigation.</p><figure class="case-evidence case-evidence--light detox-phone-figure"><img src="${img(rd+'Gamification.png')}" alt="Digital Detox goal setting screen — screen time per day, Pomodoro sessions, meditation time" loading="lazy"><figcaption>Goal setting — screen time, Pomodoro and meditation targets set in a single flow. The hourly unplugged progress card introduces the reward mechanic immediately after goal confirmation.</figcaption></figure></div></section><section class="case-section"><div><p class="eyebrow">07 / Gamification + Rewards</p></div><div><h2>Turn saved time into something real.</h2><p>The gamification system rewards users for every hour they spend away from their phone. The dot-grid progress visualisation makes accumulation satisfying and legible at a glance. For every 100 hours saved, users unlock exclusive rewards — turning abstract behaviour change into a tangible goal worth working towards.</p><div class="detox-screens-pair"><figure class="case-evidence case-evidence--light detox-phone-figure"><img src="${img(base+'iPhone 16 Pro Max.png')}" alt="Digital Detox — hourly unplugged dot grid and progress tracking" loading="lazy"><figcaption>Gamification view — each dot represents one hour saved. The progress bar and task completion counter persist at the bottom, making the goal impossible to forget.</figcaption></figure><figure class="case-evidence case-evidence--light detox-phone-figure"><img src="${img(base+'Group 100.png')}" alt="Digital Detox rewards — Time saved 120H, Amazon gift card rewards" loading="lazy"><figcaption>Reward mechanic — 120 hours saved unlocks access to exclusive shopping deals. Real, tangible motivation for continuing the behaviour change.</figcaption></figure></div></section><section class="case-section"><div><p class="eyebrow">08 / Progress + Account</p></div><div><h2>A score that reflects real effort.</h2><p>The Account screen consolidates everything into a single progress overview: Detox Score, Focus Ninja badge, daily streaks, badges collected and total time saved. This gives users a sense of identity within the app and reinforces their progress as something worth maintaining.</p><figure class="case-evidence case-evidence--light detox-phone-figure"><img src="${img(rd+'Account.png')}" alt="Digital Detox account — Detox Score 80, Focus Ninja badge, streaks, 120H time saved" loading="lazy"><figcaption>Account screen — personal Detox Score, earned badges, daily streaks and total hours saved. Progress feels earned, not just tracked.</figcaption></figure></div></section><section class="case-section"><div><p class="eyebrow">09 / Full device view</p></div><div><h2>A coherent system across every screen.</h2><p>The product visual language — orange accents, clean type, warm neutrals and the distinctive dot-grid — creates a consistent experience that feels energetic without being overwhelming. The tilted device presentation shows both primary views in context.</p><figure class="case-evidence case-evidence--light"><img src="${img(base+'deviceframes (1).png')}" alt="Digital Detox — angled device mockups showing home and progress screens" loading="lazy"><figcaption>Device mockup overview — home and tracking screens in a realistic physical context, showing how the system holds together at the UI level.</figcaption></figure></div></section><section class="case-section"><div><p class="eyebrow">10 / Key decisions</p></div><div><h2>Four decisions that shaped the product.</h2><div class="detox-decisions"><div><strong>Keep the goal visible</strong><p>Progress stays prominent instead of hiding behind a separate screen. Users need continuous awareness to maintain behaviour change.</p></div><div><strong>Use familiar patterns</strong><p>Progress indicators and reward systems borrow from interfaces users already understand, reducing the learning curve.</p></div><div><strong>Add a human Companion</strong><p>Ongoing encouragement through the Companion makes the experience feel supportive rather than like a restriction tool.</p></div><div><strong>Reward time saved</strong><p>Users gain something real from the behaviour change — they are not simply losing access to their phone.</p></div></div><p class="result-note">No user-research sample size, usability-test results or validated behavioural outcomes were provided for this project. The case study is presented around the product strategy, design decisions and MVP deliverables.</p></div></section></article>`;dialog.showModal();dialog.scrollTop=0;document.body.style.overflow='hidden'}
function openFurnichCase(p){const base='UI:UX DESIGN PROJECTS/Images/FURNICHAR Images/';content.innerHTML=`<section class="case-hero case-hero--furnich" style="--case:${p.color}"><p class="eyebrow">UI/UX design · Augmented reality · Mobile app concept · 2021</p><h1>Furnich AR</h1><p>Life beyond the manual — an augmented reality mobile app replacing confusing paper diagrams with interactive, real-world assembly guidance.</p><img src="${img(base+'hero.png')}" alt="Furnich AR — mobile interface and AR camera assembly guidance"></section><article class="case-body furnich-case" style="--accent:${p.color}"><div class="case-intro"><p class="eyebrow">Project overview</p><p>Furnich AR is an augmented reality mobile concept designed to make flat-pack furniture assembly easier, more intuitive, and frustration-free. Instead of deciphering paper manuals, searching through video tutorials, or hiring costly handymen, users receive step-by-step, real-time spatial guidance directly in their room.</p></div><section class="case-section"><div><p class="eyebrow">01 / The problem</p></div><div><h2>Flat-pack furniture is accessible. Assembling it is not.</h2><p>Ready-to-assemble furniture gives customers flexibility, but the assembly experience is fraught with friction. Users traditionally face three flawed options:</p><div class="furnich-options"><div><b>01 / Paper manuals</b><span>Vague diagrams, unlabelled screws, and confusing sequences lead to errors and dismantled parts.</span></div><div><b>02 / Online videos</b><span>Repeatedly pausing, rewinding, and wiping greasy fingers across a phone screen slows the process down.</span></div><div><b>03 / Hiring handymen</b><span>Introduces additional costs, scheduling delays, and removes the satisfaction of building it yourself.</span></div></div><blockquote class="furnich-quote">“Make furniture assembly feel like following a visual guide in the real world rather than interpreting an abstract manual.”</blockquote><div class="furnich-poll-stat"><strong>64%</strong><span>of 1,301 surveyed consumers prefer building flat-pack furniture themselves, yet struggle with unclear manuals and missing tools. The opportunity wasn't eliminating DIY — it was removing the frustration.</span></div><figure class="case-evidence case-evidence--light"><img src="${img(base+'Screenshot 2025-03-19 004929.png')}" alt="User research poll — When it comes to flat-pack furniture" loading="lazy"><figcaption>User research poll (1,301 respondents) — confirming strong DIY enthusiasm alongside persistent assembly friction.</figcaption></figure><div class="furnich-personas"><div class="furnich-persona-card"><img src="${img(base+'man.png')}" alt="Liam — Masters student persona illustration"><div><blockquote>“Finding a handyman is expensive and inconvenient. I wish there was an easier way to assemble furniture!”</blockquote><cite>Liam · Masters Student</cite></div></div><div class="furnich-persona-card"><img src="${img(base+'man (1).png')}" alt="Galen — Student & startup founder persona illustration"><div><blockquote>“Furniture manuals are a nightmare! The instructions are unclear, and I always end up frustrated.”</blockquote><cite>Galen · Student & Startup Founder</cite></div></div></div></div></section><section class="case-section"><div><p class="eyebrow">02 / The user journey</p></div><div><h2>A frictionless path from box to built.</h2><p>The product was structured around a natural progression: discovering products, preparing the workspace, accessing instructions instantly, and receiving hands-free guidance while building.</p><div class="journey"><span>Discover</span><i class="journey-sep" aria-hidden="true"><svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round"><path d="M5 12h14M13 6l6 6-6 6"/></svg></i><span>Select product</span><i class="journey-sep" aria-hidden="true"><svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round"><path d="M5 12h14M13 6l6 6-6 6"/></svg></i><span>Prepare tools</span><i class="journey-sep" aria-hidden="true"><svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round"><path d="M5 12h14M13 6l6 6-6 6"/></svg></i><span>Scan QR</span><i class="journey-sep" aria-hidden="true"><svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round"><path d="M5 12h14M13 6l6 6-6 6"/></svg></i><span>AR guidance</span><i class="journey-sep" aria-hidden="true"><svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round"><path d="M5 12h14M13 6l6 6-6 6"/></svg></i><span>Assemble</span></div><div class="furnich-reqs"><div><b>QR Access</b><span>Instant store or box scanning to launch the exact guide</span></div><div><b>AR Guidance</b><span>Real-time spatial overlays showing part placement</span></div><div><b>Tool Check</b><span>Upfront hardware and required tool identification</span></div><div><b>Hands-Free</b><span>Voice and gesture controls while hands are busy</span></div></div></div></section><section class="case-section"><div><p class="eyebrow">03 / Design iteration</p></div><div><h2>From feature-heavy directory to focused tool.</h2><p>Early wireframes and concepts explored e-commerce style browsing with complex multi-level filters, directory listings, and heavy menus. Testing revealed that users assembling furniture needed fast clarity, not an e-commerce catalog.</p><figure class="case-evidence case-evidence--light"><img src="${img(base+'Group 43.png')}" alt="Furnich AR early wireframes — information architecture and layout exploration" loading="lazy"><figcaption>Early wireframe explorations — testing navigation structures, card hierarchies, and camera access before visual refinement.</figcaption></figure><p>Iterating toward simplicity: the homepage was stripped down to prioritize recent scans, scannable furniture categories, and immediate camera/QR access.</p><figure class="case-evidence case-evidence--light"><img src="${img(base+'Frame 4.png')}" alt="Furnich AR iteration — comparing early retail directory concepts with refined product screens" loading="lazy"><figcaption>Design evolution — moving away from retail store browsing (left) toward a focused product preparation screen with tool identification (right).</figcaption></figure></div></section><section class="case-section"><div><p class="eyebrow">04 / Product discovery</p></div><div><h2>Calm, scannable, and clutter-free.</h2><p>The refined home screen provides clean visual previews of furniture, streamlined category filters (Chair, Sofa, Bed, Desks), and a persistent navigation bar with quick access to the AR camera.</p><div class="furnich-screens-pair"><figure class="case-evidence case-evidence--light furnich-phone-figure"><img src="${img(base+'Mockup.png')}" alt="Furnich AR home screen mobile mockup" loading="lazy"><figcaption>Refined Home Dashboard — welcome greeting, search, category pills, and clean furniture preview cards.</figcaption></figure><figure class="case-evidence case-evidence--light"><img src="${img(base+'Group 57.png')}" alt="Furnich AR furniture cards — Iternity Modern Chair and George Coffee Table" loading="lazy"><figcaption>Furniture Cards — store attribution, bookmarking, and clear photography give users instant context without extra screens.</figcaption></figure></div></div></section><section class="case-section"><div><p class="eyebrow">05 / Preparation & tools</p></div><div><h2>Prepare first. Assemble second.</h2><p>One of the most frustrating moments in DIY assembly is discovering missing tools halfway through the build. Furnich AR makes required tools explicit on the product page before the user begins.</p><figure class="case-evidence case-evidence--light furnich-tools-figure"><img src="${img(base+'Group 45.png')}" alt="Required tools icons — Drill, Screwdriver, Wrench, Extra pair of hands" loading="lazy"><figcaption>Visual tool identification — clear iconography communicates whether you need a drill, screwdriver, wrench, or an extra pair of hands before opening the box.</figcaption></figure><div class="furnich-screens-pair"><figure class="case-evidence case-evidence--light furnich-phone-figure"><img src="${img(base+'Group 54.png')}" alt="Furnich AR product detail screen — Iternity Modern Chair with required tools" loading="lazy"><figcaption>Product preparation view — high-resolution product preview, essential tools checklist, and one-tap launch into AR.</figcaption></figure><div class="furnich-support-card"><h3>Layered support model</h3><p>To ensure users never get stuck, Furnich AR integrates a three-tier support structure:</p><div class="furnich-support-steps"><div><b>01 / AR Guidance</b><span>Real-time 3D spatial alignment showing where parts lock in.</span></div><div><b>02 / Visual Docs</b><span>Clean component breakdowns and hardware counts.</span></div><div><b>03 / AI Assistant</b><span>Contextual troubleshooting chatbot answering tool and assembly questions on demand.</span></div></div></div></div></div></section><section class="case-section"><div><p class="eyebrow">06 / Spatial AR guidance</p></div><div><h2>In-context guidance directly in the room.</h2><p>The AR camera view serves two crucial functions:</p><p><strong>Before assembly:</strong> Users can preview the furniture in their physical space to check dimensions, fit, and aesthetic compatibility.</p><p><strong>During assembly:</strong> Computer vision and AR overlays highlight exactly where screws belong, which panel connects next, and which orientation is correct.</p><figure class="case-evidence furnich-phone-figure"><img src="${img(base+'Group 55.png')}" alt="Furnich AR camera view — spatial furniture visualization in room" loading="lazy"><figcaption>Augmented reality visualization — realistic spatial rendering in the physical room with instant access to QR scanning and assembly controls.</figcaption></figure></div></section><section class="case-section"><div><p class="eyebrow">07 / Instant QR access</p></div><div><h2>Zero-friction entry from physical packaging.</h2><p>Instead of manually searching for model names or complex serial codes, users scan the QR code printed on the flat-pack box or store receipt. The app immediately identifies the furniture and loads the interactive 3D guide.</p><figure class="case-evidence case-evidence--light furnich-phone-figure"><img src="${img(base+'Group 56.png')}" alt="Furnich AR QR code scanner interface" loading="lazy"><figcaption>QR Code Scanner — automatic viewfinder with flashlight toggle and manual serial number fallback option.</figcaption></figure></div></section><section class="case-section"><div><p class="eyebrow">08 / Complete ecosystem</p></div><div><h2>Connected flow across physical and digital touchpoints.</h2><p>Furnich AR connects discovery, physical packaging, tool preparation, and hands-free assembly into one cohesive design language.</p><figure class="case-evidence case-evidence--light"><img src="${img(base+'Frame 3.png')}" alt="Furnich AR four-screen user flow — Home, Product details, AR camera view, QR scanner" loading="lazy"><figcaption>The primary product flow — Discovery (Home), Preparation (Details & Tools), Spatial Guidance (AR View), and Instant Access (QR Scanner).</figcaption></figure><div class="furnich-principles"><div><strong>Touch</strong><p>Fast, ergonomic mobile navigation for browsing, filtering, and bookmarking products.</p></div><div><strong>Augmented Reality</strong><p>Spatial 3D instructions anchored to the physical parts in real time.</p></div><div><strong>Voice Control</strong><p>Hands-free navigation ("Next step", "Repeat step") while holding tools and panels.</p></div><div><strong>Gesture Navigation</strong><p>Contactless gestures allowing users to step through instructions without touching the phone.</p></div></div></div></section><section class="case-section"><div><p class="eyebrow">09 / Principles & takeaways</p></div><div><h2>Designing for the physical environment.</h2><div class="furnich-principles"><div><strong>Reduce cognitive load</strong><p>Show only what the user needs to do in the immediate step rather than an overwhelming 40-page diagram booklet.</p></div><div><strong>Make information visual</strong><p>Hardware, screws, and tools are rendered with clear visual icons and 3D overlays.</p></div><div><strong>Keep critical actions accessible</strong><p>QR scanning and camera modes are always accessible in one tap from anywhere in the app.</p></div><div><strong>Innovation grounded in utility</strong><p>AR technology was used strictly to solve real assembly friction, never as a gimmick.</p></div></div><p class="result-note">Furnich AR was developed as an 8-month UX concept and interaction design study (Jan–Aug 2021). The case study presents the verified design decisions, information architecture, and interface deliverables without fabricated metrics.</p></div></section></article>`;dialog.showModal();dialog.scrollTop=0;document.body.style.overflow='hidden'}
function openOwlsCase(p){const base='MARKETING PROJECTS/Owlspriority Projects/Images/';content.innerHTML=`<section class="case-hero case-hero--owls" style="--case:${p.color}"><p class="eyebrow">Digital marketing · Acquisition journey</p><h1>Owlspriority<br />Immigration</h1><p>Visa Eligibility Check & Canada Immigration Marketing Programme</p><img src="${img(p.image)}" alt="Owlspriority Immigration technical eligibility report design"></section><article class="case-body owls-case" style="--accent:${p.color}"><div class="case-intro"><p class="eyebrow">Project overview</p><p>I contributed across the Visa Eligibility Check Programme: paid acquisition, campaign creative, landing-page experiences, SEO content and ongoing email communication for prospective Canadian immigration customers.</p></div><section class="case-section"><div><p class="eyebrow">01 / The brief</p></div><div><h2>A journey that balances acquisition with education.</h2><p>Prospective applicants needed clarity on eligibility, relevant Canadian pathways, changing regulations and the next step. The programme was designed as one connected system: <strong>Discover → Learn → Check Eligibility → Sign Up → Stay Informed.</strong></p><div class="journey"><span>Discover</span><i class="journey-sep" aria-hidden="true"><svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round"><path d="M5 12h14M13 6l6 6-6 6"/></svg></i><span>Learn</span><i class="journey-sep" aria-hidden="true"><svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round"><path d="M5 12h14M13 6l6 6-6 6"/></svg></i><span>Check eligibility</span><i class="journey-sep" aria-hidden="true"><svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round"><path d="M5 12h14M13 6l6 6-6 6"/></svg></i><span>Stay informed</span></div></div></section><section class="case-section"><div><p class="eyebrow">02 / Paid media</p></div><div><h2>Capture intent on Google.</h2><p>Google Search activity supported people already exploring visa and immigration options. Campaign management, search-focused messaging, ad-copy coordination and landing-page alignment guided high-intent users into the eligibility assessment.</p><p class="journey-label">Google Search → Ad → Landing Page → Visa Eligibility Check → Lead</p><figure class="case-evidence"><img src="${img(base+'gOOGLE ADS.png')}" alt="Owlspriority Google Ads campaign creative" loading="lazy"><figcaption>Google Ads — search-led acquisition creative and messaging.</figcaption></figure></div></section><section class="case-section"><div><p class="eyebrow">03 / Paid media</p></div><div><h2>Make the opportunity clear on Meta.</h2><p>Meta campaigns used direct-response creative, placement-specific variations and clear, trustworthy messaging to build awareness and encourage the next action. The work kept campaign creative aligned with the landing-page promise.</p><figure class="case-evidence"><img src="${img(base+'Visa ELIGIBILITY CHECK META ADS.png')}" alt="Owlspriority Visa Eligibility Check Meta advertising creative" loading="lazy"><figcaption>Meta Ads — visual acquisition creative adapted for social placements.</figcaption></figure></div></section><section class="case-section"><div><p class="eyebrow">04 / Conversion</p></div><div><h2>Turn campaign attention into an eligibility check.</h2><p>The landing page made the free eligibility-check offer clear through a focused hero, benefit-led information, a simple form, pathway context, trust-building content and repeated calls to action.</p><p class="journey-label">Ad Click → Understand the Offer → Complete Form → Eligibility Assessment</p><figure class="case-evidence case-evidence--light"><img src="${img(base+'LANDING PAGE VISA ELIGIBILITY CHECK.png')}" alt="Owlspriority visa eligibility check landing page" loading="lazy"><figcaption>Landing page — conversion-focused eligibility-check journey.</figcaption></figure></div></section><section class="case-section"><div><p class="eyebrow">05 / Education</p></div><div><h2>Support the research stage with useful content.</h2><p>SEO-oriented website content answered immigration questions, developed relevant search topics and made the pathway from research to the eligibility programme easier to understand.</p><p class="journey-label">Search → Information → Trust → Eligibility Check</p></div></section><section class="case-section"><div><p class="eyebrow">06 / Lifecycle</p></div><div><h2>Keep customers informed after sign-up.</h2><p>Monthly customer newsletters translated complex immigration developments into accessible updates with relevant next-step calls to action. Each email continued the relationship after the first conversion.</p><div class="case-evidence-pair"><figure class="case-evidence case-evidence--light"><img src="${img(base+'NEWSLETTER 01.png')}" alt="Owlspriority Canada Immigration Update newsletter" loading="lazy"><figcaption>Newsletter 01 — visa regulation updates, resources and eligibility CTA.</figcaption></figure><figure class="case-evidence case-evidence--light"><img src="${img(base+'Newsletter 02 New Canada Immigration Plans.png')}" alt="Owlspriority New Canada Immigration Plans newsletter" loading="lazy"><figcaption>Newsletter 02 — immigration-plan updates and pathway information.</figcaption></figure></div></div></section><section class="case-section"><div><p class="eyebrow">07 / Outcome</p></div><div><h2>One connected marketing ecosystem.</h2><p>Paid acquisition created awareness and captured intent; the landing page supported conversion; content answered questions; and lifecycle email kept customers engaged with changing immigration information.</p><div class="owls-result"><strong>3,000+</strong><span>qualified leads generated through the digital acquisition programme.</span></div><p class="result-note">This is the confirmed performance figure supplied for the project. Additional historical metrics have not been fabricated.</p></div></section></article>`;dialog.showModal();dialog.scrollTop=0;document.body.style.overflow='hidden'}
function openSheffieldCase(p){const base='MARKETING PROJECTS/Sheffield Mind/Images/';content.innerHTML=`<section class="case-hero case-hero--sheffield" style="--case:${p.color}"><p class="eyebrow">Awareness · Participation · Sustainable funding</p><h1>Sheffield Mind</h1><p>A community campaign connecting purpose, participation and long-term support.</p><img src="${img(p.image)}" alt="Sheffield Mind community campaign hero image"></section><article class="case-body sheffield-case" style="--accent:${p.color}"><div class="case-intro"><p class="eyebrow">Project overview</p><p>A marketing and outreach campaign designed to increase awareness of Sheffield Mind, encourage community participation and explore a more sustainable supporter model. The documented campaign budget was £500.</p></div><aside class="portfolio-note"><strong>Portfolio context</strong><span>The brief identifies the following campaign visuals as reconstructed or proposed portfolio executions. They are presented as concepts, not as verified historical campaign deliverables.</span></aside><section class="case-section"><div><p class="eyebrow">01 / The challenge</p></div><div><h2>Make support feel like participation.</h2><p>The campaign needed to increase awareness of Sheffield Mind and give people a stronger reason to engage over time. Volunteering, training, events and networking transformed the proposition from a traditional donation message into a community relationship.</p><div class="journey"><span>Awareness</span><i class="journey-sep" aria-hidden="true"><svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round"><path d="M5 12h14M13 6l6 6-6 6"/></svg></i><span>Participation</span><i class="journey-sep" aria-hidden="true"><svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round"><path d="M5 12h14M13 6l6 6-6 6"/></svg></i><span>Community</span><i class="journey-sep" aria-hidden="true"><svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round"><path d="M5 12h14M13 6l6 6-6 6"/></svg></i><span>Ongoing support</span></div></div></section><section class="case-section"><div><p class="eyebrow">02 / Audience</p></div><div><h2>A message for people, professionals and local businesses.</h2><p>Community-minded people could find belonging and volunteering opportunities; professionals could access networking and development; existing supporters could deepen their connection with Sheffield Mind. The work therefore combines an empathetic cause-led message with practical reasons to get involved.</p></div></section><section class="case-section"><div><p class="eyebrow">03 / Paid social</p></div><div><h2>Invite businesses into a better mental-health conversation.</h2><p>The paid-social concept directs local professionals and businesses to a free webinar, using clear action language and practical workplace benefits. The visual system adapts the same message for Facebook, Instagram feed and Story placements.</p><figure class="case-evidence case-evidence--blue"><img src="${img(base+'metas ads.png')}" alt="Sheffield Mind webinar paid social advertising concepts" loading="lazy"><figcaption>Proposed Meta campaign system — feed, Story and supporting webinar variations.</figcaption></figure></div></section><section class="case-section"><div><p class="eyebrow">04 / LinkedIn</p></div><div><h2>Tell a richer story for a professional audience.</h2><p>The LinkedIn carousel expands the free-webinar message into an educational sequence: why workplace mental health matters, expert perspectives and a clear registration call to action. It is designed to move from awareness into consideration.</p><figure class="case-evidence case-evidence--blue"><img src="${img(base+'linkedin ads carousel ')}" alt="Sheffield Mind LinkedIn carousel advertising concept" loading="lazy"><figcaption>Proposed LinkedIn carousel — a five-part webinar and workplace-wellbeing narrative.</figcaption></figure></div></section><section class="case-section"><div><p class="eyebrow">05 / Conversion</p></div><div><h2>Make corporate support tangible.</h2><p>This conversion-page concept frames a Corporate Support Scheme around the benefits of participation: showcasing a brand for good, networking, employee engagement and positive community impact. It gives local businesses a clear route to become a partner.</p><figure class="case-evidence case-evidence--light"><img src="${img(base+'Codex Image Sep 16, 2026, 11_54_57 PM.png')}" alt="Sheffield Mind corporate support landing-page concept" loading="lazy"><figcaption>Proposed conversion-page creative — corporate partnership and community impact.</figcaption></figure></div></section><section class="case-section"><div><p class="eyebrow">06 / Email journey</p></div><div><h2>Keep the relationship moving after the first action.</h2><p>The brief defines three lifecycle touchpoints: a welcome email that introduces ways to make a difference, a get-involved email that highlights volunteering, training and events, and a community update that promotes upcoming activity.</p><div class="email-flow"><div><b>01</b><strong>Welcome</strong><span>Explore opportunities</span></div><div><b>02</b><strong>Get involved</strong><span>Volunteering, training & events</span></div><div><b>03</b><strong>Community update</strong><span>See what’s coming up</span></div></div><p class="result-note">No email artwork was supplied with the project files, so this section documents the planned customer journey rather than adding unverified visuals.</p></div></section><section class="case-section"><div><p class="eyebrow">07 / Outcome</p></div><div><h2>Awareness and fundraising working together.</h2><p>The campaign connected social, search and local awareness activity with a conversion route into events, volunteering and ongoing supporter engagement.</p><div class="owls-result"><strong>£50,000</strong><span>raised through documented marketing and outreach efforts.</span></div><p class="result-note">No additional historical performance figures were supplied, so reach, engagement, conversion and registration metrics have not been presented as actual results.</p></div></section></article>`;dialog.showModal();dialog.scrollTop=0;document.body.style.overflow='hidden'}
function openCallumCase(p){const base='MARKETING PROJECTS/529 CALLUM Whysky/Images/';content.innerHTML=`<section class="case-hero case-hero--callum" style="--case:${p.color}"><p class="eyebrow">Premium product marketing · Brand story · CRM</p><h1>CALLUM 529</h1><p>A different kind of whisky — where automotive design meets Scottish whisky-making.</p><img src="${img(p.image)}" alt="CALLUM 529 bespoke ceramic bottle"></section><article class="case-body callum-case" style="--accent:#d9966d"><div class="case-intro"><p class="eyebrow">Project overview</p><p>CALLUM 529 by Annandale is a limited-edition, unpeated single malt Scotch whisky, presented in a bespoke ceramic bottle. The campaign connected automotive design culture with Scottish heritage across paid media, a landing page and a two-part onboarding journey.</p></div><section class="case-section"><div><p class="eyebrow">01 / The idea</p></div><div><h2>Position the bottle as a designed object.</h2><p>The campaign moved beyond conventional whisky advertising. Deep navy, ceramic surfaces, warm amber and editorial typography framed CALLUM 529 as a meeting of precision, craftsmanship and attention to detail.</p><div class="journey"><span>Design</span><i class="journey-sep" aria-hidden="true"><svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round"><path d="M5 12h14M13 6l6 6-6 6"/></svg></i><span>Craft</span><i class="journey-sep" aria-hidden="true"><svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round"><path d="M5 12h14M13 6l6 6-6 6"/></svg></i><span>Heritage</span><i class="journey-sep" aria-hidden="true"><svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round"><path d="M5 12h14M13 6l6 6-6 6"/></svg></i><span>Experience</span></div><figure class="case-evidence case-evidence--callum"><img src="${img(base+'LSB_0572_landscape_vmiddle.jpg')}" alt="CALLUM 529 product lifestyle photography" loading="lazy"><figcaption>Product photography — a premium visual language rooted in material, place and atmosphere.</figcaption></figure></div></section><section class="case-section"><div><p class="eyebrow">02 / Social launch</p></div><div><h2>Build familiarity through product detail and lifestyle.</h2><p>Social content carried the campaign's visual world into a feed-led format: bottle photography, sculptural detail, tasting moments and the CALLUM × Annandale collaboration. Each post helped introduce a different part of the product story.</p><figure class="case-evidence case-evidence--light"><img src="${img(base+'social media callum.jpg')}" alt="CALLUM 529 social content system" loading="lazy"><figcaption>Social content system — product, material and tasting moments in one consistent visual world.</figcaption></figure><div class="callum-social-grid"><figure><img src="${img(base+'IMG_7042.PNG')}" alt="CALLUM 529 social post with product and gift box" loading="lazy"><figcaption>Product reveal</figcaption></figure><figure><img src="${img(base+'IMG_7043.PNG')}" alt="CALLUM 529 social post with lifestyle photography" loading="lazy"><figcaption>Experience</figcaption></figure><figure><img src="${img(base+'IMG_7044.PNG')}" alt="CALLUM 529 social post with whisky pour" loading="lazy"><figcaption>Tasting ritual</figcaption></figure><figure><img src="${img(base+'IMG_7045.PNG')}" alt="CALLUM 529 social post with bottle and glass" loading="lazy"><figcaption>Collaboration story</figcaption></figure></div></div></section><section class="case-section"><div><p class="eyebrow">03 / Conversion</p></div><div><h2>Give the product story a premium destination.</h2><p>The landing page brings together the release story, product specification, collaboration and the bespoke ceramic bottle. It lets campaign traffic move from a first impression into deeper product discovery.</p><p class="journey-label">LinkedIn + Meta → Product story → Landing page → Product exploration</p><figure class="case-evidence case-evidence--light"><img src="${img(base+'Landing Page.png')}" alt="CALLUM 529 conversion-focused landing page" loading="lazy"><figcaption>Landing page — a paced product, craft and collaboration story with clear discovery calls to action.</figcaption></figure></div></section><section class="case-section"><div><p class="eyebrow">04 / Onboarding</p></div><div><h2>Continue the story in the inbox.</h2><p>The two-email sequence makes the introduction feel editorial rather than promotional. Email 01 welcomes people to "a different kind of whisky"; Email 02 explores the shared pursuit behind CALLUM × Annandale.</p><div class="case-evidence-pair callum-emails"><figure class="case-evidence"><img src="${img(base+'Welcome & Story.png')}" alt="CALLUM 529 Welcome and Story onboarding emails" loading="lazy"><figcaption>Email 01 and Email 02 — product introduction, craft, heritage and the CALLUM × Annandale story.</figcaption></figure><figure class="case-evidence"><img src="${img(base+'Newsletter.png')}" alt="CALLUM 529 premium newsletter design" loading="lazy"><figcaption>Premium newsletter direction — product storytelling with generous space, navy, amber and editorial hierarchy.</figcaption></figure></div></div></section><section class="case-section"><div><p class="eyebrow">05 / The system</p></div><div><h2>One premium world across every touchpoint.</h2><p>LinkedIn and Meta created awareness; social and photography expanded the design-and-craft narrative; the landing page supported deeper discovery; and the onboarding sequence maintained the relationship after sign-up.</p><div class="journey"><span>Awareness</span><i class="journey-sep" aria-hidden="true"><svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round"><path d="M5 12h14M13 6l6 6-6 6"/></svg></i><span>Product story</span><i class="journey-sep" aria-hidden="true"><svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round"><path d="M5 12h14M13 6l6 6-6 6"/></svg></i><span>Landing page</span><i class="journey-sep" aria-hidden="true"><svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round"><path d="M5 12h14M13 6l6 6-6 6"/></svg></i><span>Email onboarding</span><i class="journey-sep" aria-hidden="true"><svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round"><path d="M5 12h14M13 6l6 6-6 6"/></svg></i><span>Deeper engagement</span></div><p class="result-note">No verified campaign-performance metrics were supplied for this project, so impressions, leads, conversion, revenue and ROAS have not been presented as results.</p></div></section></article>`;dialog.showModal();dialog.scrollTop=0;document.body.style.overflow='hidden'}
function openScotRailCase(p){const base='MARKETING PROJECTS/ScottRails/Images/';content.innerHTML=`<section class="case-hero case-hero--scotrail" style="--case:${p.color}"><p class="eyebrow">Campaign concept · Degree collaboration · 2021</p><h1>Edinburgh Festival<br />× ScotRail</h1><p>Encouraging festival travel through an integrated campaign concept.</p><img src="${img(base+'hero.jpg')}" alt="ScotRail Edinburgh International Festival campaign hero"></section><article class="case-body scotrail-case" style="--accent:${p.color}"><div class="case-intro"><p class="eyebrow">Project overview</p><p>As part of a degree project supporting the 2021 Edinburgh International Festival, I developed a campaign concept with ScotRail that encouraged visitors to make the train part of their festival journey. The work covered social media strategy, content creation, Google Display advertising, website copywriting, SEO content, styling, photography, railway advertising and bus-station advertising.</p></div><section class="case-section"><div><p class="eyebrow">01 / The opportunity</p></div><div><h2>Make the journey part of the experience.</h2><p>The Edinburgh International Festival brings world-leading artists and audiences together across dance, opera, music and theatre. The campaign positioned rail travel not as a functional necessity, but as part of the cultural experience itself: <strong>"Your festival experience starts on the journey."</strong></p><div class="journey"><span>Festival awareness</span><i class="journey-sep" aria-hidden="true"><svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round"><path d="M5 12h14M13 6l6 6-6 6"/></svg></i><span>Travel consideration</span><i class="journey-sep" aria-hidden="true"><svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round"><path d="M5 12h14M13 6l6 6-6 6"/></svg></i><span>ScotRail journey</span><i class="journey-sep" aria-hidden="true"><svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round"><path d="M5 12h14M13 6l6 6-6 6"/></svg></i><span>Edinburgh Festival</span></div></div></section><section class="case-section"><div><p class="eyebrow">02 / Social media content</p></div><div><h2>Festival excitement meets travel inspiration.</h2><p>Social media content used documentary-style photography, ScotRail's established blue identity and bold festival yellow typography. Three concept directions were developed: <em>Festival Journey</em> (the journey starts here), <em>Experience Edinburgh</em> (discover something extraordinary), and <em>Festival Travel</em> (your next adventure starts on the train).</p><div class="scotrail-social-grid"><figure class="case-evidence"><img src="${img(base+'EIF 1.jpg')}" alt="ScotRail social content — passenger on train with Edinburgh International Festival branding" loading="lazy"><figcaption>Social concept — a passenger's journey to the festival, capturing the emotional side of travelling to a cultural event.</figcaption></figure><figure class="case-evidence"><img src="${img(base+'EIF 2.jpg')}" alt="ScotRail social content — street performer with Edinburgh International Festival branding" loading="lazy"><figcaption>Social concept — the festival atmosphere on Edinburgh's streets, connecting the city's energy to the campaign.</figcaption></figure></div><div class="scotrail-social-grid"><figure class="case-evidence"><img src="${img(base+'EIF 3 PART 1.jpg')}" alt="ScotRail social content — Edinburgh city scene with festival branding" loading="lazy"><figcaption>Social concept — the Edinburgh environment with ScotRail branding, designed for urban and transport settings.</figcaption></figure><figure class="case-evidence"><img src="${img(base+'EIF 3 PART 2.jpg')}" alt="ScotRail social content — pedestrian with Find Your Festival messaging" loading="lazy"><figcaption>Social concept — "Find Your Festival" messaging with dynamic street photography for a younger, mobile audience.</figcaption></figure></div></div></section><section class="case-section"><div><p class="eyebrow">03 / Railway advertising</p></div><div><h2>Native to the railway journey.</h2><p>The campaign was extended into railway environments — platform billboards, station concourses and illuminated advertising panels — designed to feel native to the travel experience. Large-format photography, high-contrast messaging and strong yellow typography ensure readability at distance.</p><figure class="case-evidence"><img src="${img(base+'Railways ads.png')}" alt="ScotRail Edinburgh International Festival railway station platform advertising" loading="lazy"><figcaption>Railway platform advertising — large-format billboards at Edinburgh Waverley station, bringing the campaign into the physical journey.</figcaption></figure></div></section><section class="case-section"><div><p class="eyebrow">04 / Bus station advertising</p></div><div><h2>Extending visibility beyond rail.</h2><p>The campaign was adapted for public advertising environments outside railway stations — bus shelters, bus stations, transport hubs and high-footfall city locations. This extended campaign visibility to reach people while they were already considering travel.</p><figure class="case-evidence"><img src="${img(base+'bus stop ads.png')}" alt="ScotRail Edinburgh International Festival bus station advertising" loading="lazy"><figcaption>Bus station advertising — the campaign adapts to Edinburgh Bus Station with JCDecaux placements, maintaining the same visual identity across transport environments.</figcaption></figure></div></section><section class="case-section"><div><p class="eyebrow">05 / Google Display advertising</p></div><div><h2>A consistent system across every digital format.</h2><p>A range of Google Display creatives translated the campaign into multiple advertising dimensions — leaderboard, mobile banner, medium rectangle, large rectangle, skyscraper and wide billboard. Each format maintains the consistent visual identity: festival imagery, ScotRail branding, yellow accents and clear calls to action.</p><figure class="case-evidence"><img src="${img(base+'Google Display Ads')}" alt="ScotRail Edinburgh International Festival Google Display advertising formats" loading="lazy"><figcaption>Google Display ad system — six responsive formats from mobile banner to billboard, each carrying the campaign's visual language.</figcaption></figure></div></section><section class="case-section"><div><p class="eyebrow">06 / The campaign system</p></div><div><h2>One idea across every touchpoint.</h2><p>The campaign demonstrated how a single concept — making the journey part of the experience — can be adapted across social, display, website, railway, bus station and festival environments while maintaining a consistent visual and strategic identity. Four campaign concepts were developed, with two selected for further project development.</p><div class="journey"><span>Social</span><i class="journey-sep" aria-hidden="true"><svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round"><path d="M5 12h14M13 6l6 6-6 6"/></svg></i><span>Display ads</span><i class="journey-sep" aria-hidden="true"><svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round"><path d="M5 12h14M13 6l6 6-6 6"/></svg></i><span>Website</span><i class="journey-sep" aria-hidden="true"><svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round"><path d="M5 12h14M13 6l6 6-6 6"/></svg></i><span>Railway</span><i class="journey-sep" aria-hidden="true"><svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round"><path d="M5 12h14M13 6l6 6-6 6"/></svg></i><span>Bus station</span><i class="journey-sep" aria-hidden="true"><svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round"><path d="M5 12h14M13 6l6 6-6 6"/></svg></i><span>Festival</span></div><p class="result-note">The original project documentation does not provide verified numerical performance results. The campaign is therefore presented around its strategy and deliverables.</p></div></section></article>`;dialog.showModal();dialog.scrollTop=0;document.body.style.overflow='hidden'}
